1	//! The agent-layer search budget: cuts a fully ranked, uncapped result down to what one response may carry.
2	//!
3	//! Core returns every ranked block and holds no caps; this module is the first thing a caller does with that result.
4	use michi::TruncationOutcome;
5	
6	use crate::types::{Diagnostic, RankedBlock, SearchResponse};
7	
8	/// Texts longer than this many bytes are measured by their byte length instead of being tokenized.
9	///
10	/// BPE merging is quadratic in the length of an unbroken pretoken (200 KB of one run takes seconds), so minified
11	/// bundles and base64 blobs must not reach the tokenizer. Byte length is a proven upper bound on the token count, so
12	/// the fallback can only make a block look larger, never let one overspend the budget.
13	const TOKENIZE_BYTE_CAP: usize = 32 * 1024;
14	
15	/// The three caps one search response must stay within.
16	///
17	/// # Examples
18	///
19	/// ```
20	/// use monokl::budget::Budget;
21	///
22	/// let budget = Budget::default();
23	/// assert_eq!((budget.max_results, budget.max_tokens, budget.max_bytes), (50, 20_000, 2_097_152));
24	/// ```
25	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
26	pub struct Budget {
27	    /// The most blocks a response may carry.
28	    pub max_results: usize,
29	    /// The most tokens (`o200k_base`) the kept blocks' code may total.
30	    pub max_tokens: usize,
31	    /// The most bytes the kept blocks' code may total.
32	    pub max_bytes: usize,
33	}
34	
35	impl Default for Budget {
36	    fn default() -> Self {
37	        Self { max_results: 50, max_tokens: 20_000, max_bytes: 2_097_152 }
38	    }
39	}
40	
41	/// Returns the `o200k_base` token count of `text`, or its byte length when it is over the tokenizer's byte cap.
42	///
43	/// The byte length is an upper bound on the token count, so the count never understates.
44	///
45	/// # Examples
46	///
47	/// ```
48	/// use monokl::budget::count_tokens;
49	///
50	/// assert_eq!(count_tokens(""), 0);
51	/// assert_eq!(count_tokens("hello world"), 2);
52	/// ```
53	pub fn count_tokens(text: &str) -> usize {
54	    if text.len() > TOKENIZE_BYTE_CAP {
55	        return text.len();
56	    }
57	    tiktoken_rs::o200k_base_singleton().encode_with_special_tokens(text).len()
58	}
59	
60	/// Keeps the longest rank-order prefix of `ranked` that fits `budget` and reports what was cut.
61	///
62	/// Blocks are never split or reordered. The cut falls at the first block that would break any of the three caps, so a
63	/// block larger than the whole byte budget leaves no results. `total_before` is the count the caller had before any
64	/// cap, which may exceed `ranked.len()` when an earlier stage already dropped candidates; the response is truncated
65	/// whenever fewer blocks are kept than that. `total_bytes` sums the kept blocks' code length and `total_tokens` its
66	/// [`count_tokens`] count. `diagnostics` pass through untouched.
67	///
68	/// # Examples
69	///
70	/// ```
71	/// use monokl::budget::{apply_budget, Budget};
72	///
73	/// let response = apply_budget(Vec::new(), 0, &Budget::default(), Vec::new());
74	/// assert!(!response.truncated);
75	/// assert_eq!(response.total_blocks_before_truncation, 0);
76	/// ```
77	pub fn apply_budget(
78	    ranked: Vec<RankedBlock>,
79	    total_before: usize,
80	    budget: &Budget,
81	    diagnostics: Vec<Diagnostic>,
82	) -> SearchResponse {
83	    let mut kept = Vec::new();
84	    let mut total_bytes = 0usize;
85	    let mut total_tokens = 0usize;
86	    for block in ranked {
87	        if kept.len() >= budget.max_results {
88	            break;
89	        }
90	        let bytes = block.block.code.len();
91	        let Some(next_bytes) = total_bytes.checked_add(bytes).filter(|b| *b <= budget.max_bytes) else { break };
92	        let tokens = count_tokens(&block.block.code);
93	        let Some(next_tokens) = total_tokens.checked_add(tokens).filter(|t| *t <= budget.max_tokens) else { break };
94	        total_bytes = next_bytes;
95	        total_tokens = next_tokens;
96	        kept.push(block);
97	    }
98	
99	    let outcome = TruncationOutcome::new(kept, total_before);
100	    SearchResponse {
101	        total_blocks_before_truncation: outcome.total_before,
102	        truncated: outcome.truncated(),
103	        results: outcome.kept,
104	        total_bytes,
105	        total_tokens,
106	        diagnostics,
107	    }
108	}
109	
110	#[cfg(test)]
111	mod tests {
112	    use camino::Utf8PathBuf;
113	
114	    use super::*;
115	    use crate::types::{CodeBlock, DiagnosticKind, SymbolKind};
116	
117	    fn block(code: &str, rank: usize) -> RankedBlock {
118	        RankedBlock {
119	            block: CodeBlock {
120	                file: Utf8PathBuf::from(format!("src/f{rank}.rs")),
121	                line_start: 1,
122	                line_end: 1,
123	                node_kind: SymbolKind::Function,
124	                code: code.to_owned(),
125	                symbol_signature: None,
126	                matched_lines: Vec::new(),
127	                matched_keywords: Vec::new(),
128	            },
129	            bm25_score: 1.0,
130	            coverage_boost: 0.0,
131	            node_type_boost: 0.0,
132	            final_score: 1.0,
133	            rank,
134	            parent_context: None,
135	        }
136	    }
137	
138	    fn ranks(response: &SearchResponse) -> Vec<usize> {
139	        response.results.iter().map(|r| r.rank).collect()
140	    }
141	
142	    fn blocks(code: &str, n: usize) -> Vec<RankedBlock> {
143	        (1..=n).map(|rank| block(code, rank)).collect()
144	    }
145	
146	    fn caps(max_results: usize, max_tokens: usize, max_bytes: usize) -> Budget {
147	        Budget { max_results, max_tokens, max_bytes }
148	    }
149	
150	    #[test]
151	    fn default_budget_is_the_agent_default() {
152	        assert_eq!(Budget::default(), caps(50, 20_000, 2_097_152));
153	    }
154	
155	    #[test]
156	    fn empty_input_is_untruncated_and_keeps_diagnostics() {
157	        let diagnostics = vec![Diagnostic {
158	            kind: DiagnosticKind::Skipped,
159	            path: Some(Utf8PathBuf::from("a.ts")),
160	            message: "too large".to_owned(),
161	        }];
162	        let response = apply_budget(Vec::new(), 0, &Budget::default(), diagnostics);
163	        assert_eq!(response.results.len(), 0);
164	        assert_eq!(response.total_blocks_before_truncation, 0);
165	        assert!(!response.truncated);
166	        assert_eq!((response.total_bytes, response.total_tokens), (0, 0));
167	        assert_eq!(response.diagnostics.len(), 1);
168	        assert_eq!(response.diagnostics[0].kind, DiagnosticKind::Skipped);
169	        assert_eq!(response.diagnostics[0].path.as_deref().map(camino::Utf8Path::as_str), Some("a.ts"));
170	        assert_eq!(response.diagnostics[0].message, "too large");
171	    }
172	
173	    #[test]
174	    fn exactly_max_results_is_kept_and_one_over_is_cut() {
175	        let at = apply_budget(blocks("a", 3), 3, &caps(3, 1000, 1000), Vec::new());
176	        assert_eq!(ranks(&at), [1, 2, 3]);
177	        assert!(!at.truncated);
178	
179	        let over = apply_budget(blocks("a", 4), 4, &caps(3, 1000, 1000), Vec::new());
180	        assert_eq!(ranks(&over), [1, 2, 3]);
181	        assert!(over.truncated);
182	        assert_eq!(over.total_blocks_before_truncation, 4);
183	    }
184	
185	    #[test]
186	    fn exactly_max_bytes_is_kept_and_one_over_is_cut() {
187	        let at = apply_budget(blocks("abcd", 3), 3, &caps(10, 1000, 12), Vec::new());
188	        assert_eq!(ranks(&at), [1, 2, 3]);
189	        assert_eq!(at.total_bytes, 12);
190	        assert!(!at.truncated);
191	
192	        let over = apply_budget(blocks("abcd", 3), 3, &caps(10, 1000, 11), Vec::new());
193	        assert_eq!(ranks(&over), [1, 2]);
194	        assert_eq!(over.total_bytes, 8);
195	        assert!(over.truncated);
196	    }
197	
198	    #[test]
199	    fn exactly_max_tokens_is_kept_and_one_over_is_cut() {
200	        let per_block = count_tokens("fn a() {}");
201	        assert_eq!(per_block, 4);
202	        let at = apply_budget(blocks("fn a() {}", 3), 3, &caps(10, per_block * 3, 1000), Vec::new());
203	        assert_eq!(ranks(&at), [1, 2, 3]);
204	        assert_eq!(at.total_tokens, 12);
205	        assert!(!at.truncated);
206	
207	        let over = apply_budget(blocks("fn a() {}", 3), 3, &caps(10, per_block * 3 - 1, 1000), Vec::new());
208	        assert_eq!(ranks(&over), [1, 2]);
209	        assert_eq!(over.total_tokens, 8);
210	        assert!(over.truncated);
211	    }
212	
213	    #[test]
214	    fn earliest_block_to_break_any_limit_sets_the_cut() {
215	        // Block 2 breaks the token cap, block 3 would have broken the byte cap.
216	        let input = vec![block("a", 1), block("fn a() {}", 2), block(&"x".repeat(500), 3)];
217	        let response = apply_budget(input, 3, &caps(10, 3, 100), Vec::new());
218	        assert_eq!(ranks(&response), [1]);
219	        assert!(response.truncated);
220	
221	        // The byte cap trips on block 2 while the token and result caps still have room.
222	        let input = vec![block("a", 1), block(&"x ".repeat(60), 2), block("a", 3)];
223	        let response = apply_budget(input, 3, &caps(10, 1000, 100), Vec::new());
224	        assert_eq!(ranks(&response), [1]);
225	
226	        // A later small block is not pulled in past the cut.
227	        let input = vec![block("a", 1), block("fn a() {}", 2), block("a", 3)];
228	        let response = apply_budget(input, 3, &caps(10, 3, 100), Vec::new());
229	        assert_eq!(ranks(&response), [1]);
230	    }
231	
232	    #[test]
233	    fn block_larger_than_the_byte_budget_keeps_nothing() {
234	        let response = apply_budget(blocks(&"y".repeat(50), 2), 2, &caps(10, 1000, 49), Vec::new());
235	        assert_eq!(response.results.len(), 0);
236	        assert!(response.truncated);
237	        assert_eq!(response.total_blocks_before_truncation, 2);
238	        assert_eq!((response.total_bytes, response.total_tokens), (0, 0));
239	    }
240	
241	    #[test]
242	    fn total_before_beyond_input_marks_the_response_truncated() {
243	        let response = apply_budget(blocks("a", 2), 9, &Budget::default(), Vec::new());
244	        assert_eq!(ranks(&response), [1, 2]);
245	        assert_eq!(response.total_blocks_before_truncation, 9);
246	        assert!(response.truncated);
247	    }
248	
249	    #[test]
250	    fn token_counts_match_the_o200k_encoder_for_known_strings() {
251	        let bpe = tiktoken_rs::o200k_base().unwrap();
252	        for (text, expected) in [("", 0), ("hello world", 2), ("fn a() {}", 4), ("let x = 1;\n", 6)] {
253	            assert_eq!(count_tokens(text), expected, "{text:?}");
254	            assert_eq!(bpe.encode_with_special_tokens(text).len(), expected, "{text:?}");
255	        }
256	    }
257	
258	    #[test]
259	    fn multibyte_text_counts_tokens_not_bytes() {
260	        let text = "日本語のコメント";
261	        let bpe = tiktoken_rs::o200k_base().unwrap();
262	        assert_eq!(count_tokens(text), bpe.encode_with_special_tokens(text).len());
263	        assert!(count_tokens(text) < text.len());
264	    }
265	
266	    #[test]
267	    fn text_over_the_byte_cap_is_measured_by_its_length() {
268	        let at_cap = "a ".repeat(TOKENIZE_BYTE_CAP / 2);
269	        assert_eq!(at_cap.len(), TOKENIZE_BYTE_CAP);
270	        // Sixteen thousand "a" words plus the trailing space as its own token.
271	        assert_eq!(count_tokens(&at_cap), TOKENIZE_BYTE_CAP / 2 + 1);
272	
273	        let over_cap = format!("{at_cap}a");
274	        assert_eq!(count_tokens(&over_cap), TOKENIZE_BYTE_CAP + 1);
275	    }
276	
277	    #[test]
278	    fn text_well_under_the_byte_cap_is_tokenized_not_measured_by_its_length() {
279	        let text = "a ".repeat(1024);
280	        assert_eq!(text.len(), 2048);
281	        let tokens = tiktoken_rs::o200k_base().unwrap().encode_with_special_tokens(&text).len();
282	        assert_eq!(count_tokens(&text), tokens);
283	        assert_eq!(tokens, 1025);
284	    }
285	
286	    #[test]
287	    fn text_far_over_the_byte_cap_is_measured_by_its_length() {
288	        let text = "a ".repeat(20 * 1024);
289	        assert_eq!(text.len(), 40 * 1024);
290	        assert_eq!(count_tokens(&text), 40 * 1024);
291	    }
292	
293	    #[test]
294	    fn totals_do_not_depend_on_how_tight_the_token_cap_is() {
295	        // With a loose cap every block fits on its byte length alone; the reported total must still be the exact count.
296	        let input = || vec![block("fn a() {}", 1), block("let x = 1;\n", 2)];
297	        let loose = apply_budget(input(), 2, &caps(10, 1_000_000, 1_000_000), Vec::new());
298	        let tight = apply_budget(input(), 2, &caps(10, 10, 1_000_000), Vec::new());
299	        assert_eq!((loose.total_tokens, tight.total_tokens), (10, 10));
300	        assert_eq!((loose.total_bytes, tight.total_bytes), (20, 20));
301	        assert!(!tight.truncated);
302	    }
303	
304	    #[test]
305	    fn apply_budget_is_deterministic() {
306	        let run = || {
307	            let r = apply_budget(blocks("fn a() {}", 6), 6, &caps(4, 1000, 1000), Vec::new());
308	            (ranks(&r), r.total_bytes, r.total_tokens, r.truncated)
309	        };
310	        assert_eq!(run(), run());
311	    }
312	}
