211	    const LISTED_FILES: usize = 3;
212	    let mut groups: BTreeMap<(&str, Option<&'static str>), Vec<&str>> = BTreeMap::new();
213	    for d in diagnostics {
214	        let verb = d.path.as_ref().map(|_| match d.kind {
215	            DiagnosticKind::Degraded => "degraded",
216	            DiagnosticKind::Skipped => "skipped",
217	            DiagnosticKind::Warning => "warned",
218	            DiagnosticKind::LossyRead => "read lossily",
