221	        paths.extend(d.path.as_deref().map(Utf8Path::as_str));
222	    }
223	    groups
224	        .into_iter()
225	        .map(|((message, verb), mut paths)| match verb {
226	            Some(verb) => {
227	                paths.sort_unstable();
228	                let n = paths.len();
229	                let listed = paths[..n.min(LISTED_FILES)].join(", ");
230	                let more = if n > LISTED_FILES { format!(", ...and {} more", n - LISTED_FILES) } else { String::new() };
231	                format!("{n} {} {verb}: {message}: {listed}{more}", if n == 1 { "file" } else { "files" })
