239	///
240	/// It bypasses [`ToDomainError`] because this is not a [`MonoklError`]: it means this module built an invalid row or
241	/// field, not that the caller supplied bad input.
242	pub fn toon_validation_error(e: &michi::toon::ToonError) -> michi::DomainError {
243	    michi::DomainError::new(michi::ErrorCode::ExternalFailure, format!("toon_render_invalid: {e}")).retryable(false)
244	}
