246	/// Renders a [`ToonProjection`] as a TOON document.
247	///
248	/// # Errors
249	///
250	/// Returns a [`toon_validation_error`] if the projection's table fails michi's validation.
251	#[expect(clippy::result_large_err, reason = "the error type is michi's DomainError, which agent output is built from")]
252	pub fn render_projection<const N: usize, T: ToonProjection<N>>(value: &T) -> Result<String, michi::DomainError> {
253	    let rows: Vec<Vec<Value>> = value.toon_rows().into_iter().map(|row| row.to_vec()).collect();
254	    let fields: Vec<String> = T::FIELDS.iter().map(|s| (*s).to_string()).collect();
255	
256	    let opts = michi::toon::ToonOptions::new(T::TYPE_NAME, fields, rows.clone()).total_count(value.toon_total_count());
257	    if let Err(e) = opts.validate() {
258	        return Err(toon_validation_error(&e));
259	    }
260	
261	    let mut resp = michi::AgentResponse::new(T::TYPE_NAME).items(rows, T::FIELDS.as_slice()).hints(value.toon_hints());
262	    if let Some(n) = value.toon_total_count() {
263	        resp = resp.total_count(n);
264	    }
265	    Ok(resp.render_toon())
266	}
