cat >> crates/monokl/tests/cli.rs <<'EOF'

const SEARCH_HEADER: &str = "search[2]{file,lineStart,lineEnd,nodeKind,symbolSignature,snippet,rank,finalScore}:";
const PRICE_ROW_1: &str = "  src/components/Button.tsx,11,18,function,\"function Button({ label, price, onClick, disabled }: ButtonProps)\",\"12: const priceValid = price === undefined || validatePrice(price).valid;\\n14: <button onClick={onClick} disabled={disabled || !priceValid}>\",1,1.164513";
const PRICE_ROW_2: &str = "  src/utils/validation.ts,8,12,function,\"function validatePrice(price: number): ValidationResult\",\"9: if (price < 0) return { valid: false, message: 'Price cannot be negative' };\\n10: if (price > 1_000_000) return { valid: false, message: formatCurrency(1_000_000) + ' is the maximum' };\",2,1.163847";
const CUT_TAIL: &str = "totalCount: 8\nhelp[1]: showing N of 8; raise the cap or refine the query with +term or -term\n";

fn cut_tail(shown: usize) -> String {
    CUT_TAIL.replace('N', &shown.to_string())
}

fn two_rows_cut() -> String {
    format!("{SEARCH_HEADER}\n{PRICE_ROW_1}\n{PRICE_ROW_2}\n{}", cut_tail(2))
}

fn one_row_cut() -> String {
    format!("{}\n{PRICE_ROW_1}\n{}", SEARCH_HEADER.replace("[2]", "[1]"), cut_tail(1))
}

#[test]
fn a_cut_by_rows_keeps_the_first_rows_and_says_so() {
    let output = monokl(&["search", "price", ".", "--max-results", "2"]);
    assert_eq!(stdout(&output), two_rows_cut());
}

#[test]
fn a_cut_by_bytes_counts_the_printed_rows_and_not_the_blocks() {
    let printed = PRICE_ROW_1.len() + PRICE_ROW_2.len();
    // The two blocks' code is far larger than the cap that still keeps both rows.
    assert_eq!(stdout(&monokl(&["search", "price", ".", "--max-bytes", &printed.to_string()])), two_rows_cut());
    assert_eq!(stdout(&monokl(&["search", "price", ".", "--max-bytes", &(printed - 1).to_string()])), one_row_cut());
}

#[test]
fn a_cut_by_tokens_counts_the_printed_rows_and_not_the_blocks() {
    let printed = monokl::budget::count_tokens(PRICE_ROW_1) + monokl::budget::count_tokens(PRICE_ROW_2);
    assert_eq!(stdout(&monokl(&["search", "price", ".", "--max-tokens", &printed.to_string()])), two_rows_cut());
    assert_eq!(stdout(&monokl(&["search", "price", ".", "--max-tokens", &(printed - 1).to_string()])), one_row_cut());
